#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_init_game_instance_normal_word_truncated(void) {
    struct game_instance game;
    const char *word = "supercalifragilisticexpialidocious"; // length > 29

    init_game_instance(&game, word);

    TEST_ASSERT_EQUAL_INT(29, game.size);
    TEST_ASSERT_EQUAL_STRING("supercalifragilisticexpial", game.current_word);
    TEST_ASSERT_EQUAL_CHAR('\0', game.current_word[29]);

    TEST_ASSERT_EQUAL_STRING("_____________________________", game.hidden);
    TEST_ASSERT_EQUAL_CHAR('\0', game.hidden[29]);

    TEST_ASSERT_EQUAL_INT(0, game.incorrect);
    TEST_ASSERT_EQUAL_INT(0, game.guesses_size);

    for (int i = 0; i < sizeof(game.guesses); i++) {
        TEST_ASSERT_EQUAL_CHAR(0, game.guesses[i]);
    }
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_init_game_instance_normal_word_truncated);
    return UNITY_END();
}

